create or replace function private.protect_notification_identity() returns trigger language plpgsql security definer set search_path = '' as $$ begin if tg_op='UPDATE' then if new.user_id is distinct from old.user_id or new.id is distinct from old.id or new.created_at is distinct from old.created_at or new.title is distinct from old.title or new.body is distinct from old.body or new.ref_table is distinct from old.ref_table or new.ref_id is distinct from old.ref_id then if not private.is_admin_user() then raise exception 'Notification identity and content are system controlled'; end if; end if; end if; return new; end; $$; drop trigger if exists trg_protect_notification_identity on public.notifications; create trigger trg_protect_notification_identity before update on public.notifications for each row execute function private.protect_notification_identity(); revoke insert,delete on table public.notifications from authenticated;
